    (async function() {
        // --- 1. DATA FETCHING ---
        let mvuData = {};
        try {
            const message = (await getChatMessages(getCurrentMessageId()))[0];
            mvuData = message.data || {};
        } catch (e) {
            console.error("Mikasa Status: Could not fetch MVU data.", e);
            return;
        }

        // **REQUIREMENT 1: Use stat_data exclusively**
        const data = mvuData.stat_data || {};
        if (!data.三笠) {
             console.error("Mikasa Status: '三笠' data block not found in stat_data.");
             return;
        }

        // --- 2. HELPER FUNCTIONS ---
        function safeGet(path, defaultValue = '--') {
            const value = _.get(data, path);
            if (value === undefined || value === null) return defaultValue;
            // stat_data values are arrays: [value, description]
            if (Array.isArray(value)) return value[0]; 
            return value;
        }

        function updateProgressBar(barId, valueId, value, max = 100) {
            const bar = document.getElementById(barId);
            const valueEl = document.getElementById(valueId);
            if (!bar || !valueEl) return;

            const numericValue = parseInt(value, 10);
            if (isNaN(numericValue)) return;

            const percentage = (numericValue / max) * 100;
            bar.style.width = `${Math.min(Math.max(percentage, 0), 100)}%`;
            valueEl.textContent = `${numericValue} / ${max}`;
        }

        function updateValue(elementId, value) {
            const el = document.getElementById(elementId);
            if (el) el.textContent = value;
        }

        // --- 3. LOGIC & RENDERING ---
        // Convert numeric codes to text descriptions
        const shameCode = safeGet('三笠.认知.身体羞耻', 1);
        let shameText = '未知';
        if (shameCode == 1) shameText = '冲突/羞耻';
        else if (shameCode == 2) shameText = '接纳/沉溺';
        else if (shameCode == 3) shameText = '统一/神圣';

        const dominanceCode = safeGet('三笠.关系网.支配倾向', -10);
        let dominanceText = '被动探索';
        if (dominanceCode < -5) dominanceText = '绝对服从';
        else if (dominanceCode > 0) dominanceText = '主动引导';

        // --- 4. UPDATE DISPLAY ---
        updateValue('mikasa-date', safeGet('三笠.世界.日期', '未知日期'));

        // 认知
        updateProgressBar('bar-moral', 'val-moral', safeGet('三笠.认知.道德感', 0));
        updateProgressBar('bar-defense', 'val-defense', safeGet('三笠.认知.心理防线', 0));
        updateValue('val-shame', `${shameCode} (${shameText})`);

        // 属性
        updateValue('val-depravity', `${safeGet('三笠.属性.沉沦等级', 1)} / 6`);
        updateProgressBar('bar-desire', 'val-desire', safeGet('三笠.属性.欲望', 0));
        updateProgressBar('bar-guilt', 'val-guilt', safeGet('三笠.属性.内疚感', 0));
        updateProgressBar('bar-rationalize', 'val-rationalize', safeGet('三笠.属性.自我说服', 0));
        updateProgressBar('bar-addiction', 'val-addiction', safeGet('三笠.属性.成瘾度', 0));

        // 关系网
        updateProgressBar('bar-miss-user', 'val-miss-user', safeGet('三笠.关系网.对{{user}}的思念', 0));
        updateProgressBar('bar-miss-eren', 'val-miss-eren', safeGet('三笠.关系网.对艾伦的思念', 0));
        updateValue('val-dominance', `${dominanceCode} (${dominanceText})`);

        // 经验
        updateValue('exp-oral', safeGet('三笠.经验.口交', 0));
        updateValue('exp-breast', safeGet('三笠.经验.乳交', 0));
        updateValue('exp-frottage', safeGet('三笠.经验.素股', 0));
        updateValue('exp-anal', safeGet('三笠.经验.后庭', 0));
        updateValue('exp-vaginal', safeGet('三笠.经验.蜜穴', 0));
        updateValue('exp-womb', safeGet('三笠.经验.子宫', 0));

        // 状态
        updateValue('val-status', safeGet('三笠.状态', '无'));
    })();
</script>
