        return;
    }

    const data = mvuData.stat_data || {};
    if (!data.三笠) {
        console.error("Dossier Error: '三笠' data block not found in stat_data.");
    }

    function safeGet(path, defaultValue = 0) {
        const value = _.get(data, path);
        if (value === undefined || value === null) return defaultValue;
        return Array.isArray(value) ? value[0] : value;
    }

    // === START: IMAGE UPDATE LOGIC ===
    const depravityLevel = safeGet('三笠.属性.沉沦等级', 1);
