    const gridLabelsContainer = document.getElementById('grid-labels-container');
    gridLinesContainer.innerHTML = '';
    gridLabelsContainer.innerHTML = '';

    for (let i = 0; i < numAxes; i++) {
        const angle = angleSlice * i;
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'use');
        line.setAttributeNS('http://www.w3.org/1999/xlink', 'href', '#grid-line');
        line.setAttribute('transform', `rotate(${angle * 180 / Math.PI})`);
        gridLinesContainer.appendChild(line);

        const labelAngle = angleSlice * i - Math.PI / 2;
        const labelRadius = 115; 
        const lx = labelRadius * Math.cos(labelAngle);
        const ly = labelRadius * Math.sin(labelAngle);
        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        text.setAttribute('x', lx);
        text.setAttribute('y', ly);
        text.setAttribute('dy', '0.35em');
        text.textContent = radarLabels[i];
        gridLabelsContainer.appendChild(text);
    }

    const desire = safeGet('三笠.属性.欲望');
    const missUser = safeGet('三笠.关系网.对{{user}}的思念'); 
    const missEren = safeGet('三笠.关系网.对艾伦的思念', 100);
    const moral = safeGet('三笠.认知.道德感', 100);
    const defense = safeGet('三笠.认知.心理防线', 100);
    const dominance = safeGet('三笠.关系网.支配倾向', -10);
    const addiction = safeGet('三笠.属性.成瘾度');
    const guilt = safeGet('三笠.属性.内疚感');
    const rationalize = safeGet('三笠.属性.自我说服');

    const radarValues = [
        desire,
        Math.max(0, missEren + (100 - missUser)) / 2,
        (moral + defense) / 2,
        Math.max(0, ((-dominance + 10) / 20) * 100),
        addiction
    ];

    const points = radarValues.map((val, i) => getRadarPoint(val, i)).join(' ');
    document.getElementById('radar-polygon').setAttribute('points', points);

    updateText('dossier-date', safeGet('三笠.世界.日期', '未知'));
    updateText('val-moral', `${moral} / 100`);
    updateText('val-defense', `${defense} / 100`);

    updateText('val-depravity', `${depravityLevel} / 6`);
