    updateText('val-eren-presence', safeGet('三笠.世界.艾伦存在感', 0));
    updateText('val-rumor', safeGet('三笠.世界.流言调查指数', 0));
    const totalConflict = Math.max(1, guilt + rationalize);
    const guiltPercent = (guilt / totalConflict) * 100;
    const rationalizePercent = 100 - guiltPercent;
    document.getElementById('meter-guilt').style.width = `${guiltPercent}%`;
    document.getElementById('meter-rationalize').style.width = `${rationalizePercent}%`;
    updateText('val-guilt', guilt);
    updateText('val-rationalize', rationalize);

    updateText('exp-oral', safeGet('三笠.经验.口交'));
    updateText('exp-breast', safeGet('三笠.经验.乳交'));
    updateText('exp-frottage', safeGet('三笠.经验.素股'));
    updateText('exp-anal', safeGet('三笠.经验.后庭'));
    updateText('exp-vaginal', safeGet('三笠.经验.蜜穴'));
    updateText('exp-womb', safeGet('三笠.经验.子宫'));

    const status = safeGet('三笠.状态', '');
    if (status && status !== '无' && status !== '""') {
        document.getElementById('alert-section-container').style.display = 'block';
        updateText('alert-text', `当前行为余韵: ${status}`);
    } else {
        document.getElementById('alert-section-container').style.display = 'none';
    }

})();
</script>
</body>
</html>
